import React, { useEffect, useState, useRef } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import axios from 'axios';
import { useAuth } from '../context/AuthContext';
import Footer from '../components/Footer';

const API = process.env.REACT_APP_API_URL || 'http://localhost:5000';

const jobCategoryCharacters = {
  security: { char: '/images/char-gojo-idle.png', color: '#00B4D8', quote: 'The strongest protect others.' },
  it: { char: '/images/char-megumi-idle.png', color: '#7C3AED', quote: 'Every problem has a solution.' },
  teaching: { char: '/images/char-nanami-idle.png', color: '#FFB703', quote: 'Prepare and deliver your best.' },
  cooking: { char: '/images/char-senshi-idle.png', color: '#FF6B35', quote: 'Passion makes the difference.' },
  customer: { char: '/images/char-nobara-idle.png', color: '#EC4899', quote: 'Walk in like you own it.' },
  construction: { char: '/images/char-todo-idle.png', color: '#78716C', quote: 'Build the world others live in.' },
  accounting: { char: '/images/char-yuki-idle.png', color: '#7C3AED', quote: 'Numbers tell powerful stories.' },
  driving: { char: '/images/char-panda-idle.png', color: '#06D6A0', quote: 'Every journey needs a great driver.' },
  admin: { char: '/images/char-yaga-idle.png', color: '#1E3A5F', quote: 'Great orgs run on great admins.' },
  healthcare: { char: '/images/char-shoko-idle.png', color: '#06D6A0', quote: 'Healing takes courage. You have it.' },
  default: { char: '/images/pose8.png', color: '#00B4D8', quote: 'Your next opportunity awaits.' }
};

const getJobCharacter = (title = '', category = '') => {
  const t = (title + category).toLowerCase();
  if (t.includes('security') || t.includes('guard')) return jobCategoryCharacters.security;
  if (t.includes('it') || t.includes('tech') || t.includes('software') || t.includes('computer')) return jobCategoryCharacters.it;
  if (t.includes('teach') || t.includes('tutor') || t.includes('educat')) return jobCategoryCharacters.teaching;
  if (t.includes('cook') || t.includes('chef') || t.includes('cater') || t.includes('food')) return jobCategoryCharacters.cooking;
  if (t.includes('customer') || t.includes('service') || t.includes('retail') || t.includes('sales')) return jobCategoryCharacters.customer;
  if (t.includes('construct') || t.includes('engineer') || t.includes('build')) return jobCategoryCharacters.construction;
  if (t.includes('account') || t.includes('finance') || t.includes('audit')) return jobCategoryCharacters.accounting;
  if (t.includes('driver') || t.includes('driving') || t.includes('deliver') || t.includes('transport')) return jobCategoryCharacters.driving;
  if (t.includes('admin') || t.includes('office') || t.includes('clerk')) return jobCategoryCharacters.admin;
  if (t.includes('nurse') || t.includes('health') || t.includes('medical') || t.includes('clinical')) return jobCategoryCharacters.healthcare;
  return jobCategoryCharacters.default;
};

const Particle = ({ color, style }) => (
  <div style={{
    position: 'absolute',
    width: '6px',
    height: '6px',
    borderRadius: '50%',
    background: color,
    opacity: 0.4,
    animation: `particle-float ${style.duration}s linear ${style.delay}s infinite`,
    left: style.left,
    top: style.top,
    pointerEvents: 'none'
  }} />
);

const SpeechBubble = ({ text, color = '#00B4D8', side = 'bottom', visible }) => {
  if (!visible) return null;
  return (
    <div className="animate-bubblePop" style={{
      background: '#fff',
      border: `2px solid ${color}`,
      borderRadius: '14px',
      padding: '10px 14px',
      fontSize: '12px',
      fontWeight: 600,
      color: '#0F172A',
      maxWidth: '200px',
      textAlign: 'center',
      position: 'relative',
      boxShadow: '0 4px 16px rgba(0,0,0,0.1)',
      lineHeight: 1.5
    }}>
      {text}
      <div style={{
        position: 'absolute',
        bottom: side === 'bottom' ? '-10px' : 'auto',
        top: side === 'top' ? '-10px' : 'auto',
        left: '50%',
        transform: 'translateX(-50%)',
        borderLeft: '8px solid transparent',
        borderRight: '8px solid transparent',
        borderTop: side === 'bottom' ? `10px solid ${color}` : 'none',
        borderBottom: side === 'top' ? `10px solid ${color}` : 'none',
      }} />
    </div>
  );
};

const CountUp = ({ target, duration = 2000 }) => {
  const [count, setCount] = useState(0);
  const ref = useRef(null);
  useEffect(() => {
    const observer = new IntersectionObserver(([entry]) => {
      if (entry.isIntersecting) {
        let start = 0;
        const step = target / (duration / 16);
        const timer = setInterval(() => {
          start += step;
          if (start >= target) { setCount(target); clearInterval(timer); }
          else setCount(Math.floor(start));
        }, 16);
      }
    });
    if (ref.current) observer.observe(ref.current);
    return () => observer.disconnect();
  }, [target, duration]);
  return <span ref={ref}>{count}</span>;
};

const LandingPage = () => {
  const { user, darkMode, toggleDark } = useAuth();
  const navigate = useNavigate();
  const [jobs, setJobs] = useState([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [activeQ, setActiveQ] = useState(null);
  const [hoveredChar, setHoveredChar] = useState(null);
  const [heroVisible, setHeroVisible] = useState(false);

  useEffect(() => {
    const fetchJobs = async () => {
      try {
        const res = await axios.get(`${API}/api/jobs`);
        setJobs(res.data);
      } catch (err) { console.error(err); }
      finally { setLoading(false); }
    };
    fetchJobs();
    setTimeout(() => setHeroVisible(true), 100);
  }, []);

  const filtered = jobs.filter(j =>
    j.title?.toLowerCase().includes(search.toLowerCase()) ||
    j.company?.name?.toLowerCase().includes(search.toLowerCase()) ||
    j.location?.toLowerCase().includes(search.toLowerCase())
  );

  const jobTypeLabel = { full_time: 'Full Time', part_time: 'Part Time', contract: 'Contract', internship: 'Internship' };
  const jobTypeColor = { full_time: { bg: '#DCFCE7', color: '#166534' }, part_time: { bg: '#DBEAFE', color: '#1E40AF' }, contract: { bg: '#FEF9C3', color: '#854D0E' }, internship: { bg: '#F3E8FF', color: '#6B21A8' } };

  const faqs = [
    { q: 'Is KibaliGuard free to use?', a: 'Yes! Creating an account, browsing jobs and applying is completely free for all job seekers.' },
    { q: 'What happens to my documents after I apply?', a: 'Your documents are stored securely and can only be accessed by someone who has your consent for that specific purpose. You can see every access attempt in real time and stop sharing at any time.' },
    { q: 'Can I delete my data from a company\'s system?', a: 'Yes. You can withdraw your consent at any time from your dashboard. The moment you do, the company loses access to your documents immediately.' },
    { q: 'What is the Talent Pool?', a: 'The Talent Pool lets you register your skills so companies can find you for matching roles. Your listing lasts 6 months and you can remove yourself at any time.' },
    { q: 'How does KibaliGuard protect my data?', a: 'Every access to your documents requires your explicit consent matching the exact purpose. Our system enforces the Kenya Data Protection Act 2019 technically, not just as a written policy.' },
    { q: 'Can I update my CV after applying?', a: 'Yes. You can manage your document sharing rules at any time from your dashboard, and update the documents companies have access to.' }
  ];

  const particles = [
    { color: '#00B4D8', style: { duration: 8, delay: 0, left: '10%', top: '80%' } },
    { color: '#FF6B35', style: { duration: 12, delay: 2, left: '30%', top: '90%' } },
    { color: '#06D6A0', style: { duration: 10, delay: 1, left: '60%', top: '85%' } },
    { color: '#FFB703', style: { duration: 9, delay: 3, left: '80%', top: '75%' } },
    { color: '#7C3AED', style: { duration: 11, delay: 0.5, left: '45%', top: '95%' } },
  ];

  const supportingCharacters = [
    { char: '/images/char-gojo-idle.png', label: 'Security', color: '#00B4D8' },
    { char: '/images/char-senshi-idle.png', label: 'Catering', color: '#FF6B35' },
    { char: '/images/char-nobara-idle.png', label: 'Customer Service', color: '#EC4899' },
    { char: '/images/char-nanami-idle.png', label: 'Teaching', color: '#FFB703' },
  ];

  return (
    <div style={{ minHeight: '100vh', display: 'flex', flexDirection: 'column', background: '#fff', fontFamily: 'Inter, sans-serif', overflow: 'hidden' }}>

      {/* ─── NAVBAR ─── */}
      <nav style={{ background: 'rgba(15,23,42,0.95)', backdropFilter: 'blur(12px)', padding: '0 32px', display: 'flex', alignItems: 'center', justifyContent: 'space-between', height: '68px', position: 'sticky', top: 0, zIndex: 100, boxShadow: '0 2px 20px rgba(0,0,0,0.3)' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
          <img src="/images/pose1.png" alt="Kiba" style={{ width: '36px', height: '36px', objectFit: 'contain' }} />
          <span style={{ color: '#00B4D8', fontWeight: 900, fontSize: '22px', letterSpacing: '-1px' }}>KibaliGuard</span>
        </div>
        <div style={{ display: 'flex', alignItems: 'center', gap: '12px', flexWrap: 'wrap' }}>
          <a href="#how-it-works" style={{ color: '#CBD5E1', textDecoration: 'none', fontWeight: 600, fontSize: '14px' }}>How It Works</a>
          <a href="#characters" style={{ color: '#CBD5E1', textDecoration: 'none', fontWeight: 600, fontSize: '14px' }}>Our Team</a>
          <a href="#jobs" style={{ color: '#CBD5E1', textDecoration: 'none', fontWeight: 600, fontSize: '14px' }}>Jobs</a>
          <a href="#talent" style={{ color: '#CBD5E1', textDecoration: 'none', fontWeight: 600, fontSize: '14px' }}>Talent Pool</a>
          <button onClick={toggleDark} style={{ background: 'rgba(0,180,216,0.15)', border: '1.5px solid #00B4D8', borderRadius: '8px', padding: '6px 10px', cursor: 'pointer', display: 'flex', alignItems: 'center' }}>
            <span style={{ fontSize: '16px' }}>{darkMode ? '☀️' : '🌙'}</span>
          </button>
          {user ? (
            <button onClick={() => navigate(user.role === 'admin' ? '/admin' : user.role === 'staff' ? '/staff' : '/dashboard')}
              style={{ padding: '9px 22px', background: '#00B4D8', color: '#fff', border: 'none', borderRadius: '10px', fontWeight: 700, fontSize: '14px', cursor: 'pointer' }}>
              My Dashboard
            </button>
          ) : (
            <>
              <Link to="/login" style={{ color: '#CBD5E1', textDecoration: 'none', fontWeight: 600, fontSize: '14px' }}>Sign In</Link>
              <Link to="/register" style={{ padding: '9px 22px', background: '#FF6B35', color: '#fff', borderRadius: '10px', textDecoration: 'none', fontWeight: 800, fontSize: '14px', boxShadow: '0 4px 14px rgba(255,107,53,0.4)' }}>
                Get Started Free
              </Link>
            </>
          )}
        </div>
      </nav>

      {/* ─── HERO ─── */}
      <div className="hero-gradient" style={{ padding: '80px 32px 60px', position: 'relative', overflow: 'hidden', minHeight: '600px', display: 'flex', alignItems: 'center' }}>
        {particles.map((p, i) => <Particle key={i} color={p.color} style={p.style} />)}

        <div style={{ maxWidth: '1200px', margin: '0 auto', width: '100%', display: 'flex', alignItems: 'center', gap: '48px', flexWrap: 'wrap', justifyContent: 'center', position: 'relative', zIndex: 1 }}>

          <div style={{ flex: 1, minWidth: '280px', maxWidth: '560px' }}>
            <div className={heroVisible ? 'animate-slideInLeft' : ''} style={{ display: 'inline-flex', alignItems: 'center', gap: '8px', background: 'rgba(6,214,160,0.15)', border: '1px solid rgba(6,214,160,0.4)', borderRadius: '999px', padding: '6px 16px', marginBottom: '28px' }}>
              <span style={{ width: '8px', height: '8px', borderRadius: '50%', background: '#06D6A0', boxShadow: '0 0 8px #06D6A0', display: 'inline-block', animation: 'pulse-glow 2s infinite' }} />
              <span style={{ color: '#06D6A0', fontSize: '13px', fontWeight: 700 }}>Kenya Data Protection Act 2019 Compliant</span>
            </div>

            <h1 className={`${heroVisible ? 'animate-slideInLeft' : ''} delay-100`} style={{ fontSize: '52px', fontWeight: 900, color: '#fff', lineHeight: 1.1, letterSpacing: '-1.5px', marginBottom: '24px' }}>
              Find your next job.<br />
              <span className="shimmer-text">Keep your data yours.</span>
            </h1>

            <p className={`${heroVisible ? 'animate-slideInLeft' : ''} delay-200`} style={{ fontSize: '18px', color: '#BAE6FD', lineHeight: 1.8, marginBottom: '36px', maxWidth: '480px' }}>
              Most job sites take your CV and never tell you what happens to it. KibaliGuard is different. You decide who sees your documents, why they see them, and for how long. Take it all back anytime.
            </p>

            <div className={`${heroVisible ? 'animate-slideInLeft' : ''} delay-300`} style={{ display: 'flex', gap: '14px', flexWrap: 'wrap', marginBottom: '48px' }}>
              <Link to="/register" style={{ padding: '16px 36px', background: '#FF6B35', color: '#fff', borderRadius: '14px', textDecoration: 'none', fontWeight: 800, fontSize: '16px', boxShadow: '0 8px 24px rgba(255,107,53,0.45)', transition: 'all 0.2s' }}>
                Start for Free
              </Link>
              <a href="#how-it-works" style={{ padding: '16px 36px', background: 'rgba(255,255,255,0.1)', color: '#fff', borderRadius: '14px', textDecoration: 'none', fontWeight: 700, fontSize: '16px', border: '1px solid rgba(255,255,255,0.25)' }}>
                See How It Works
              </a>
            </div>

            <div className={`${heroVisible ? 'animate-slideInLeft' : ''} delay-400`} style={{ display: 'flex', gap: '36px', flexWrap: 'wrap' }}>
              {[
                { val: 100, suffix: '%', label: 'Data Control' },
                { val: 0, suffix: '', label: 'Unauthorized Access' },
                { val: 247, suffix: '+', label: 'Jobs Available' }
              ].map(s => (
                <div key={s.label}>
                  <div style={{ fontSize: '32px', fontWeight: 900, color: '#00B4D8', fontFamily: 'Roboto Mono, monospace' }}>
                    <CountUp target={s.val} />{s.suffix}
                  </div>
                  <div style={{ fontSize: '13px', color: '#94A3B8', fontWeight: 500 }}>{s.label}</div>
                </div>
              ))}
            </div>
          </div>

          <div className={`${heroVisible ? 'animate-slideInRight' : ''} delay-200`} style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '16px', position: 'relative' }}>
            <div style={{ position: 'relative', display: 'flex', alignItems: 'flex-end', gap: '16px' }}>
              <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '8px' }}>
                <div style={{ fontSize: '11px', color: '#00B4D8', fontWeight: 700, textTransform: 'uppercase', letterSpacing: '1px' }}>Loid Forger</div>
                <img src="/images/char-loid-idle.png" alt="Loid" className="character-img-left animate-float" style={{ width: '120px', height: '160px', objectFit: 'contain', filter: 'drop-shadow(0 8px 20px rgba(0,0,0,0.3))' }}
                  onError={e => e.target.style.display = 'none'} />
              </div>

              <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '8px' }}>
                <div style={{ width: '280px', height: '340px', clipPath: 'polygon(50% 0%, 100% 18%, 100% 62%, 50% 100%, 0% 62%, 0% 18%)', background: 'linear-gradient(180deg, #1E3A5F, #0F172A)', border: '3px solid #00B4D8', display: 'flex', alignItems: 'center', justifyContent: 'center', position: 'relative', animation: 'kibashield-pulse-blue 3s ease-in-out infinite' }}>
                  <div style={{ position: 'absolute', top: '16px', left: '50%', transform: 'translateX(-50%)', fontSize: '18px' }}>🔒</div>
                  <div style={{ position: 'absolute', top: '32px', left: '50%', transform: 'translateX(-50%)', display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
                    <div style={{ width: '14px', height: '14px', borderRadius: '50%', background: '#06D6A0', boxShadow: '0 0 12px #06D6A0', animation: 'kibashield-pulse-blue 2s infinite' }} />
                    <div style={{ width: '3px', height: '24px', background: 'linear-gradient(to bottom, #94A3B8, #475569)', borderRadius: '2px' }} />
                  </div>
                  <div style={{ marginTop: '40px', animation: 'kibashield-bounce 2.5s ease-in-out infinite' }}>
                    <img src="/images/pose8.png" alt="Kiba" style={{ width: '180px', height: '210px', objectFit: 'contain', filter: 'drop-shadow(0 8px 20px rgba(0,0,0,0.4))' }}
                      onError={e => { e.target.style.display = 'none'; }} />
                  </div>
                </div>
                <div style={{ background: 'rgba(0,180,216,0.15)', borderRadius: '12px', padding: '10px 20px', textAlign: 'center', border: '1px solid rgba(0,180,216,0.3)' }}>
                  <p style={{ color: '#fff', fontWeight: 700, fontSize: '13px', margin: 0 }}>Kiba is protecting your data</p>
                  <p style={{ color: '#94A3B8', fontSize: '11px', margin: '3px 0 0' }}>Your personal data consent assistant</p>
                </div>
              </div>

              <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '8px' }}>
                <div style={{ fontSize: '11px', color: '#EC4899', fontWeight: 700, textTransform: 'uppercase', letterSpacing: '1px' }}>Anya Forger</div>
                <img src="/images/char-anya-excited.png" alt="Anya" className="character-img-right animate-float" style={{ width: '110px', height: '150px', objectFit: 'contain', filter: 'drop-shadow(0 8px 20px rgba(0,0,0,0.3))' }}
                  onError={e => e.target.style.display = 'none'} />
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* ─── TRUSTED BY ─── */}
      <div style={{ background: '#F0F9FF', padding: '24px 32px', borderBottom: '1px solid #E0F2FE' }}>
        <div style={{ maxWidth: '900px', margin: '0 auto', textAlign: 'center' }}>
          <p style={{ color: '#64748B', fontSize: '13px', fontWeight: 700, textTransform: 'uppercase', letterSpacing: '1px', marginBottom: '16px' }}>Trusted by companies across Kenya</p>
          <div style={{ display: 'flex', gap: '32px', justifyContent: 'center', flexWrap: 'wrap' }}>
            {['KibaliGuard Digital Services', 'Nairobi Security Ltd', 'TechHire Kenya', 'BuildRight Construction', 'Savanna Restaurant'].map(c => (
              <span key={c} style={{ fontSize: '14px', fontWeight: 700, color: '#94A3B8' }}>{c}</span>
            ))}
          </div>
        </div>
      </div>

      {/* ─── CHARACTER SHOWCASE ─── */}
      <div id="characters" style={{ padding: '80px 32px', background: '#fff' }}>
        <div style={{ maxWidth: '1100px', margin: '0 auto', textAlign: 'center' }}>
          <span style={{ background: '#FEF3C7', color: '#92400E', fontSize: '12px', fontWeight: 700, padding: '4px 14px', borderRadius: '999px', textTransform: 'uppercase', letterSpacing: '1px', display: 'inline-block', marginBottom: '16px' }}>Meet The Team</span>
          <h2 style={{ fontSize: '38px', fontWeight: 900, color: '#0F172A', marginBottom: '12px', letterSpacing: '-1px' }}>
            Real roles. Real characters.
          </h2>
          <p style={{ color: '#64748B', fontSize: '16px', marginBottom: '48px', maxWidth: '500px', margin: '0 auto 48px', lineHeight: 1.7 }}>
            Every job category has a character who knows that world inside out. They are here to guide you.
          </p>

          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(160px, 1fr))', gap: '20px' }}>
            {[
              { char: '/images/char-gojo-idle.png', name: 'Gojo', role: 'Security', color: '#00B4D8', bg: '#E0F9FF' },
              { char: '/images/char-senshi-idle.png', name: 'Senshi', role: 'Catering', color: '#FF6B35', bg: '#FFF0EB' },
              { char: '/images/char-nobara-idle.png', name: 'Nobara', role: 'Customer Service', color: '#EC4899', bg: '#FDF2F8' },
              { char: '/images/char-nanami-idle.png', name: 'Nanami', role: 'Teaching', color: '#FFB703', bg: '#FFFBEB' },
              { char: '/images/char-megumi-idle.png', name: 'Megumi', role: 'IT Support', color: '#7C3AED', bg: '#F5F3FF' },
              { char: '/images/char-shoko-idle.png', name: 'Shoko', role: 'Healthcare', color: '#06D6A0', bg: '#ECFDF5' },
              { char: '/images/char-todo-idle.png', name: 'Todo', role: 'Construction', color: '#78716C', bg: '#FAFAF9' },
              { char: '/images/char-yuki-idle.png', name: 'Yuki', role: 'Accounting', color: '#7C3AED', bg: '#F5F3FF' },
              { char: '/images/char-panda-idle.png', name: 'Panda', role: 'Driving', color: '#06D6A0', bg: '#ECFDF5' },
              { char: '/images/char-yaga-idle.png', name: 'Yaga', role: 'Administration', color: '#0F172A', bg: '#F8FAFC' },
            ].map((c, i) => (
              <div key={c.name} className={`hover-lift animate-slideUp delay-${Math.min((i % 5 + 1) * 100, 500)}`}
                style={{ background: c.bg, borderRadius: '20px', padding: '24px 16px', display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '12px', border: `2px solid transparent`, transition: 'all 0.2s', cursor: 'pointer' }}
                onMouseEnter={e => { e.currentTarget.style.borderColor = c.color; setHoveredChar(c.name); }}
                onMouseLeave={e => { e.currentTarget.style.borderColor = 'transparent'; setHoveredChar(null); }}>
                <img src={c.char} alt={c.name} style={{ width: '80px', height: '110px', objectFit: 'contain', animation: 'floatCharacter 3s ease-in-out infinite', filter: 'drop-shadow(0 4px 12px rgba(0,0,0,0.15))' }}
                  onError={e => { e.target.style.display = 'none'; }} />
                <div>
                  <p style={{ fontWeight: 800, fontSize: '14px', color: '#0F172A', margin: 0 }}>{c.name}</p>
                  <p style={{ fontSize: '12px', color: c.color, fontWeight: 700, margin: '2px 0 0' }}>{c.role}</p>
                </div>
                {hoveredChar === c.name && (
                  <div className="animate-bubblePop" style={{ background: '#fff', border: `1.5px solid ${c.color}`, borderRadius: '10px', padding: '8px 10px', fontSize: '11px', color: '#0F172A', fontWeight: 600, textAlign: 'center', lineHeight: 1.5 }}>
                    {jobCategoryCharacters[c.role.toLowerCase().replace(' ', '')] ? jobCategoryCharacters[c.role.toLowerCase().replace(' ', '')].quote : 'Your opportunity awaits.'}
                  </div>
                )}
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* ─── HOW IT WORKS ─── */}
      <div id="how-it-works" style={{ padding: '80px 32px', background: '#F0F9FF' }}>
        <div style={{ maxWidth: '1000px', margin: '0 auto', textAlign: 'center' }}>
          <span style={{ background: '#DBEAFE', color: '#1E40AF', fontSize: '12px', fontWeight: 700, padding: '4px 14px', borderRadius: '999px', textTransform: 'uppercase', letterSpacing: '1px', display: 'inline-block', marginBottom: '16px' }}>Simple Process</span>
          <h2 style={{ fontSize: '38px', fontWeight: 900, color: '#0F172A', marginBottom: '48px', letterSpacing: '-1px' }}>Three steps to full control</h2>
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(260px, 1fr))', gap: '28px' }}>
            {[
              { num: '01', icon: '📤', title: 'Apply for jobs', desc: 'Browse open positions and upload your documents — CV, National ID, certificates. Everything in one place, securely stored.', color: '#00B4D8' },
              { num: '02', icon: '🔐', title: 'Set your rules', desc: 'Decide who can see each document, exactly why they can see it, and for how many days. You are in complete control.', color: '#FF6B35' },
              { num: '03', icon: '👁️', title: 'Track everything', desc: 'See every single access attempt the moment it happens. Know who tried, when they tried, and whether it was allowed.', color: '#06D6A0' }
            ].map((step, i) => (
              <div key={step.num} className={`hover-lift animate-slideUp delay-${(i + 1) * 200}`}
                style={{ background: '#fff', borderRadius: '24px', padding: '36px 28px', textAlign: 'left', position: 'relative', boxShadow: '0 4px 24px rgba(0,0,0,0.06)', border: '1px solid #E0F2FE' }}>
                <div style={{ position: 'absolute', top: '20px', right: '20px', fontSize: '52px', fontWeight: 900, color: '#F0F9FF', fontFamily: 'Roboto Mono, monospace', lineHeight: 1 }}>{step.num}</div>
                <div style={{ width: '56px', height: '56px', borderRadius: '16px', background: `${step.color}20`, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '28px', marginBottom: '20px' }}>{step.icon}</div>
                <h3 style={{ fontSize: '20px', fontWeight: 800, color: '#0F172A', marginBottom: '12px' }}>{step.title}</h3>
                <p style={{ fontSize: '14px', color: '#64748B', lineHeight: 1.7 }}>{step.desc}</p>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* ─── TALENT POOL TEASER ─── */}
      <div id="talent" style={{ padding: '80px 32px', background: 'linear-gradient(135deg, #0F172A 0%, #1E3A5F 60%, #00B4D8 100%)', position: 'relative', overflow: 'hidden' }}>
        <div style={{ maxWidth: '1000px', margin: '0 auto', display: 'flex', alignItems: 'center', gap: '48px', flexWrap: 'wrap', justifyContent: 'center', position: 'relative', zIndex: 1 }}>

          <div style={{ display: 'flex', gap: '16px', alignItems: 'flex-end' }}>
            <img src="/images/char-chilchuck-idle.png" alt="Chilchuck" className="character-img animate-float" style={{ width: '100px', height: '140px', objectFit: 'contain', filter: 'drop-shadow(0 8px 20px rgba(0,0,0,0.4))' }} onError={e => e.target.style.display = 'none'} />
            <img src="/images/pose2.png" alt="Kiba" className="animate-float" style={{ width: '120px', height: '150px', objectFit: 'contain', filter: 'drop-shadow(0 8px 20px rgba(0,0,0,0.4))', animationDelay: '0.5s' }} onError={e => e.target.style.display = 'none'} />
          </div>

          <div style={{ flex: 1, minWidth: '280px' }}>
            <span style={{ background: 'rgba(6,214,160,0.2)', color: '#06D6A0', fontSize: '12px', fontWeight: 700, padding: '4px 14px', borderRadius: '999px', textTransform: 'uppercase', letterSpacing: '1px', display: 'inline-block', marginBottom: '16px' }}>Talent Pool</span>
            <h2 style={{ fontSize: '38px', fontWeight: 900, color: '#fff', marginBottom: '16px', letterSpacing: '-1px', lineHeight: 1.2 }}>
              Let the right job<br />find <span className="shimmer-text">you.</span>
            </h2>
            <p style={{ color: '#BAE6FD', fontSize: '16px', lineHeight: 1.8, marginBottom: '28px' }}>
              Not actively applying? Join the Talent Pool. Select your skills, get notified when matching jobs are posted, and remove yourself instantly if you get hired elsewhere.
            </p>
            <div style={{ display: 'flex', gap: '12px', flexWrap: 'wrap', marginBottom: '28px' }}>
              {['6-month consent period', 'Withdraw anytime', 'Skill-based matching', 'Instant notifications'].map(f => (
                <span key={f} style={{ background: 'rgba(255,255,255,0.1)', color: '#fff', padding: '6px 14px', borderRadius: '999px', fontSize: '13px', fontWeight: 600, border: '1px solid rgba(255,255,255,0.2)' }}>✓ {f}</span>
              ))}
            </div>
            <Link to={user ? '/talent-pool' : '/register'} style={{ display: 'inline-block', padding: '14px 32px', background: '#06D6A0', color: '#0F172A', borderRadius: '12px', textDecoration: 'none', fontWeight: 800, fontSize: '16px', boxShadow: '0 8px 24px rgba(6,214,160,0.4)' }}>
              Join the Talent Pool
            </Link>
          </div>
        </div>
      </div>

      {/* ─── JOBS SECTION ─── */}
      <div id="jobs" style={{ padding: '80px 32px', background: '#fff' }}>
        <div style={{ maxWidth: '1100px', margin: '0 auto' }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '16px', marginBottom: '36px' }}>
            <div>
              <span style={{ background: '#DBEAFE', color: '#1E40AF', fontSize: '12px', fontWeight: 700, padding: '4px 14px', borderRadius: '999px', textTransform: 'uppercase', letterSpacing: '1px', display: 'inline-block', marginBottom: '12px' }}>Open Positions</span>
              <h2 style={{ fontSize: '34px', fontWeight: 900, color: '#0F172A', margin: 0, letterSpacing: '-0.5px' }}>Jobs available right now</h2>
              <p style={{ color: '#64748B', fontSize: '14px', marginTop: '6px' }}>{jobs.length} opportunities with full data protection</p>
            </div>
            <input type="text" placeholder="Search jobs, companies or locations..." value={search} onChange={e => setSearch(e.target.value)}
              style={{ padding: '12px 20px', border: '2px solid #E0F2FE', borderRadius: '12px', fontSize: '14px', fontFamily: 'Inter, sans-serif', outline: 'none', width: '280px', maxWidth: '100%', background: '#F0F9FF' }} />
          </div>

          {loading ? (
            <div style={{ textAlign: 'center', padding: '60px', color: '#64748B', fontSize: '16px' }}>Loading available positions...</div>
          ) : filtered.length === 0 ? (
            <div style={{ textAlign: 'center', padding: '60px 0' }}>
              <img src="/images/pose3.png" alt="Kiba" style={{ width: '80px', height: '80px', objectFit: 'contain', marginBottom: '16px' }} onError={e => e.target.style.display = 'none'} />
              <p style={{ color: '#64748B', fontSize: '15px' }}>No jobs found. Check back soon!</p>
            </div>
          ) : (
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(320px, 1fr))', gap: '20px' }}>
              {filtered.map((job, i) => {
                const charData = getJobCharacter(job.title, job.skillCategories?.join(' ') || '');
                const typeStyle = jobTypeColor[job.jobType] || jobTypeColor.contract;
                return (
                  <div key={job._id} className={`hover-lift animate-slideUp delay-${Math.min((i % 4 + 1) * 100, 400)}`}
                    style={{ background: '#fff', borderRadius: '20px', padding: '24px', border: '1.5px solid #E0F2FE', cursor: 'pointer', boxShadow: '0 4px 16px rgba(0,0,0,0.05)', position: 'relative', overflow: 'hidden' }}
                    onClick={() => navigate(`/jobs/${job._id}`)}>

                    <div style={{ position: 'absolute', top: 0, right: 0, width: '6px', height: '100%', background: charData.color }} />

                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: '16px' }}>
                      <div style={{ flex: 1 }}>
                        <span style={{ padding: '3px 10px', borderRadius: '999px', fontSize: '11px', fontWeight: 700, background: typeStyle.bg, color: typeStyle.color, display: 'inline-block', marginBottom: '8px' }}>
                          {jobTypeLabel[job.jobType] || job.jobType}
                        </span>
                        <h3 style={{ fontSize: '17px', fontWeight: 800, color: '#0F172A', marginBottom: '4px', lineHeight: 1.3 }}>{job.title}</h3>
                        <p style={{ fontSize: '14px', color: '#00B4D8', fontWeight: 700 }}>{job.company?.name}</p>
                      </div>
                      <img src={charData.char} alt="" className="job-character" style={{ width: '70px', height: '90px', objectFit: 'contain', flexShrink: 0, marginLeft: '12px' }}
                        onError={e => e.target.style.display = 'none'} />
                    </div>

                    <div style={{ display: 'flex', gap: '12px', flexWrap: 'wrap', marginBottom: '16px' }}>
                      <span style={{ fontSize: '13px', color: '#64748B', display: 'flex', alignItems: 'center', gap: '4px' }}>📍 {job.location}</span>
                      <span style={{ fontSize: '13px', color: '#64748B', display: 'flex', alignItems: 'center', gap: '4px' }}>📅 {new Date(job.deadline).toLocaleDateString()}</span>
                      {job.salaryRange && <span style={{ fontSize: '13px', color: '#64748B' }}>💰 {job.salaryRange}</span>}
                    </div>

                    {job.requiredDocuments?.length > 0 && (
                      <div style={{ display: 'flex', gap: '6px', flexWrap: 'wrap', marginBottom: '16px' }}>
                        {job.requiredDocuments.slice(0, 3).map(d => (
                          <span key={d.name} style={{ background: '#F0F9FF', color: '#0369A1', fontSize: '11px', fontWeight: 600, padding: '2px 8px', borderRadius: '999px', border: '1px solid #BAE6FD' }}>📄 {d.name}</span>
                        ))}
                        {job.requiredDocuments.length > 3 && <span style={{ fontSize: '11px', color: '#94A3B8' }}>+{job.requiredDocuments.length - 3} more</span>}
                      </div>
                    )}

                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                      <span style={{ fontSize: '12px', color: '#94A3B8', fontFamily: 'Roboto Mono, monospace' }}>{job.applicantCount || 0} applicant{job.applicantCount !== 1 ? 's' : ''}</span>
                      <button onClick={e => { e.stopPropagation(); navigate(user ? `/apply/${job._id}` : '/register'); }}
                        style={{ padding: '9px 20px', background: charData.color, color: job.color === '#FFB703' ? '#0F172A' : '#fff', border: 'none', borderRadius: '10px', fontWeight: 700, fontSize: '13px', cursor: 'pointer', fontFamily: 'Inter, sans-serif' }}>
                        {user ? 'Apply Now' : 'Register to Apply'}
                      </button>
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </div>
      </div>

      {/* ─── FAQ ─── */}
      <div style={{ padding: '80px 32px', background: '#F0F9FF' }}>
        <div style={{ maxWidth: '720px', margin: '0 auto' }}>
          <div style={{ textAlign: 'center', marginBottom: '48px' }}>
            <span style={{ background: '#FEE2E2', color: '#991B1B', fontSize: '12px', fontWeight: 700, padding: '4px 14px', borderRadius: '999px', textTransform: 'uppercase', letterSpacing: '1px', display: 'inline-block', marginBottom: '16px' }}>Got Questions?</span>
            <h2 style={{ fontSize: '36px', fontWeight: 900, color: '#0F172A', letterSpacing: '-1px' }}>We have answers</h2>
          </div>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
            {faqs.map((faq, i) => (
              <div key={i} className="hover-lift" style={{ background: '#fff', borderRadius: '16px', overflow: 'hidden', border: '1.5px solid #E0F2FE' }}>
                <button onClick={() => setActiveQ(activeQ === i ? null : i)}
                  style={{ width: '100%', padding: '20px 24px', background: 'none', border: 'none', cursor: 'pointer', display: 'flex', justifyContent: 'space-between', alignItems: 'center', gap: '16px', fontFamily: 'Inter, sans-serif' }}>
                  <span style={{ fontWeight: 700, fontSize: '15px', color: '#0F172A', textAlign: 'left' }}>{faq.q}</span>
                  <span style={{ fontSize: '20px', color: '#00B4D8', transform: activeQ === i ? 'rotate(45deg)' : 'rotate(0deg)', transition: 'transform 0.2s', flexShrink: 0 }}>+</span>
                </button>
                {activeQ === i && (
                  <div className="animate-slideUp" style={{ padding: '0 24px 20px', borderTop: '1px solid #E0F2FE' }}>
                    <p style={{ fontSize: '14px', color: '#64748B', lineHeight: 1.8, margin: '16px 0 0' }}>{faq.a}</p>
                  </div>
                )}
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* ─── FINAL CTA ─── */}
      <div style={{ padding: '80px 32px', background: 'linear-gradient(135deg, #0F172A 0%, #1E3A5F 50%, #00B4D8 100%)', position: 'relative', overflow: 'hidden', textAlign: 'center' }}>
        <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'flex-end', gap: '16px', marginBottom: '32px' }}>
          <img src="/images/char-yor-idle.png" alt="Yor" className="animate-float" style={{ width: '90px', height: '130px', objectFit: 'contain', filter: 'drop-shadow(0 8px 20px rgba(0,0,0,0.4))' }} onError={e => e.target.style.display = 'none'} />
          <img src="/images/pose2.png" alt="Kiba" className="animate-float" style={{ width: '110px', height: '140px', objectFit: 'contain', filter: 'drop-shadow(0 8px 20px rgba(0,0,0,0.4))', animationDelay: '0.3s' }} onError={e => e.target.style.display = 'none'} />
          <img src="/images/char-loid-idle.png" alt="Loid" className="animate-float" style={{ width: '90px', height: '130px', objectFit: 'contain', filter: 'drop-shadow(0 8px 20px rgba(0,0,0,0.4))', animationDelay: '0.6s' }} onError={e => e.target.style.display = 'none'} />
        </div>
        <h2 style={{ fontSize: '44px', fontWeight: 900, color: '#fff', marginBottom: '16px', letterSpacing: '-1px' }}>
          Take control of your data today.
        </h2>
        <p style={{ fontSize: '18px', color: '#BAE6FD', marginBottom: '40px', maxWidth: '500px', margin: '0 auto 40px', lineHeight: 1.7 }}>
          Register free in under 2 minutes. Your documents stay yours.
        </p>
        <div style={{ display: 'flex', gap: '16px', justifyContent: 'center', flexWrap: 'wrap' }}>
          <Link to="/register" style={{ padding: '18px 48px', background: '#FF6B35', color: '#fff', borderRadius: '14px', textDecoration: 'none', fontWeight: 800, fontSize: '18px', boxShadow: '0 8px 32px rgba(255,107,53,0.4)' }}>
            Get Started Free
          </Link>
          <Link to="/login" style={{ padding: '18px 48px', background: 'rgba(255,255,255,0.1)', color: '#fff', borderRadius: '14px', textDecoration: 'none', fontWeight: 700, fontSize: '18px', border: '1px solid rgba(255,255,255,0.3)' }}>
            Sign In
          </Link>
        </div>
      </div>

      <Footer />
    </div>
  );
};

export default LandingPage;
